fun {motive} ctorIdx =>
  bif Nat.ble ctorIdx 0 then PULift.{u, u} ((a : Real) → motive (Bhola.Tree.leaf a))
  else PULift.{u, u} ((a a_1 : Bhola.Tree) → (a_2 : Real) → motive (Bhola.Tree.add a a_1 a_2))

