∀ (err : Nat → Nat → Real) (k : Nat) (xs : List.{0} Real),
  Eq.{1}
    (HDiv.hDiv.{0, 0, 0}
      (HAdd.hAdd.{0, 0, 0} (List.length.{0} (Bhola.rounds err k (List.map.{0, 0} Bhola.Tree.leaf xs))) 1) 2)
    (CeilDiv.ceilDiv.{0, 0} (List.length.{0} xs) (HPow.hPow.{0, 0, 0} 2 (HAdd.hAdd.{0, 0, 0} k 1)))
